    vector<int> a(n + 1);
    for (int i = 0; i < k; ++i)
        a[i] = 1;
    for (int i = k; i <= n; ++i) {
        a[i] = 0;
        for (int j = i - k; j < i; ++j)
            a[i] += a[j];
    }
    return a[n];
}

